import { USERS, expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test(
    "current user is returned for a valid session",
    { tag: "@AUTH-04" },
    async ({ apiAs }) => {
      // Arrange: signed in as the seeded member
      const member = await apiAs("member");

      // Act
      const response = await member.get("/api/me");

      // Assert
      expect(response.status()).toBe(200);
      const profile = await response.json();
      expect(profile.email).toBe(USERS.member);
      expect(profile.role).toBe("member");
      expect(profile.tenant.name).toBe("Northwind Supply");
    },
  );
});
